<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import type { AxiosInstance } from 'axios';

type Result = { seed: number; status: string; completed_epochs?: number; eligible_epochs?: number; best_epoch?: { epoch: number; loss: number }; error?: string };
type SeedJob = { id: string; status: string; seeds: number[]; completed_seeds: number; results: Result[]; train_timerange: string; error?: string };
type Preview = { train_timerange: string; seeds: number[]; epochs_each: number; total_epochs: number; estimated_input_bytes: number; note: string };
type Scope = { per_parameter_override: { available: boolean; reason: string; safe_action: string }; parameters: { name: string; space: string; low: number; high: number; value: unknown }[] };
const props = defineProps<{ api: AxiosInstance; strategy: string; revision: string; settings: Record<string, unknown>; presetId?: string; busy?: boolean }>();
const capabilities = ref<{ spaces: { id: string; enabled: boolean }[]; losses: { id: string; label: string }[] }>();
const scope = ref<Scope>();
const spaces = ref<string[]>([]), loss = ref('SharpeHyperOptLossDaily'), seedsText = ref('42, 137, 911'), epochs = ref(30), minTrades = ref(10);
const preview = ref<Preview>(), selected = ref<SeedJob>(), jobs = ref<SeedJob[]>([]), working = ref(false), error = ref('');
let poll: ReturnType<typeof setInterval> | undefined;
const seeds = computed(() => seedsText.value.split(',').map(x => Number(x.trim())));
const body = computed(() => ({ strategy: props.strategy, revision: props.revision, preset_id: props.presetId, settings: props.settings, epochs: epochs.value, spaces: spaces.value, loss: loss.value, min_trades: minTrades.value, workers: 1, seeds: seeds.value }));
function message(e: unknown) { const x = e as { response?: { data?: { detail?: unknown } }; message?: string }; return String(x.response?.data?.detail ?? x.message ?? e); }
async function refresh() { try { jobs.value = (await props.api.get('/studio/seed-experiments', { params: { strategy: props.strategy } })).data.jobs ?? []; if (selected.value) selected.value = (await props.api.get('/studio/seed-experiments/' + selected.value.id)).data; } catch (e) { error.value = message(e); } }
async function act(task: () => Promise<void>) { working.value = true; error.value = ''; try { await task(); } catch (e) { error.value = message(e); } finally { working.value = false; } }
async function inspect() { await act(async () => { preview.value = (await props.api.post('/studio/seed-experiments/preview', body.value)).data; }); }
async function start() { if (!preview.value) return; await act(async () => { selected.value = (await props.api.post('/studio/seed-experiments', body.value)).data; preview.value = undefined; await refresh(); }); }
async function open(id: string) { await act(async () => { selected.value = (await props.api.get('/studio/seed-experiments/' + id)).data; }); }
async function cancel() { if (!selected.value) return; await act(async () => { selected.value = (await props.api.post('/studio/seed-experiments/' + selected.value!.id + '/cancel', {})).data; }); }
onMounted(() => { void refresh(); void props.api.get('/studio/optimization-parameter-scope/' + props.strategy).then(response => { scope.value = response.data; }).catch(e => { error.value = message(e); }); void props.api.get('/studio/optimization-capabilities/' + props.strategy).then(response => { capabilities.value = response.data; const enabled = capabilities.value?.spaces.filter(x => x.enabled).map(x => x.id) ?? []; spaces.value = enabled.filter(x => ['buy', 'sell'].includes(x)); if (!spaces.value.length && enabled[0]) spaces.value = [enabled[0]]; if (!capabilities.value?.losses.some(x => x.id === loss.value)) loss.value = capabilities.value?.losses[0]?.id ?? ''; }).catch(e => { error.value = message(e); }); poll = setInterval(() => { if (selected.value && ['prepared', 'running', 'cancelling'].includes(selected.value.status)) void refresh(); }, 3500); });
onUnmounted(() => { if (poll) clearInterval(poll); });
</script>

<template>
  <div class="seed"><h3>Kiểm tra nhiều seed Hyperopt</h3><p>Chạy các seed đã định trước trên cùng dữ liệu train bằng Hyperopt native 2026.9, lần lượt từng child. Bảng này chỉ phản ánh tập học; OOS và holdout cần kiểm định riêng. Không tự chọn tham số hay thay paper.</p>
    <div class="grid"><label>Seed, cách nhau dấu phẩy<input v-model="seedsText" @input="preview=undefined"></label><label>Epoch mỗi seed<input v-model.number="epochs" type="number" min="1" max="250" @input="preview=undefined"></label><label>Số lệnh tối thiểu<input v-model.number="minTrades" type="number" min="1" @input="preview=undefined"></label><label>Nhóm tham số (Ctrl để chọn nhiều)<select v-model="spaces" multiple @change="preview=undefined"><option v-for="item in capabilities?.spaces.filter(x=>x.enabled)" :key="item.id" :value="item.id">{{item.id}}</option></select></label><label>Loss native<select v-model="loss" @change="preview=undefined"><option v-for="item in capabilities?.losses" :key="item.id" :value="item.id">{{item.label}}</option></select></label></div>
    <div class="actions"><button :disabled="working || busy || !spaces.length" @click="inspect">Xem kế hoạch nhiều seed</button><button :disabled="working || busy || !preview" @click="start">Chạy đúng kế hoạch đã xem</button><button :disabled="working" @click="refresh">Tải lại</button></div><p v-if="error" class="error" role="alert">{{error}}</p>
    <div v-if="preview" class="box"><h4>Ngân sách trước khi chạy</h4><p>Train {{preview.train_timerange}} · {{preview.seeds.join(', ')}} · {{preview.epochs_each}} epoch mỗi seed · tổng {{preview.total_epochs}} epoch · khoảng {{(preview.estimated_input_bytes/1048576).toFixed(1)}} MB dữ liệu sao chép.</p><p>{{preview.note}}</p></div>
    <div class="box"><h4>Lịch sử</h4><p v-if="!jobs.length">Chưa có thí nghiệm nhiều seed.</p><div class="actions"><button v-for="job in jobs" :key="job.id" @click="open(job.id)">{{job.id.slice(0,10)}} · {{job.status}} · {{job.completed_seeds}}/{{job.seeds.length}}</button></div></div>
    <div v-if="selected" class="box"><div class="actions"><h4>Thí nghiệm {{selected.id.slice(0,10)}} · {{selected.status}}</h4><button v-if="['prepared','running'].includes(selected.status)" :disabled="working" @click="cancel">Dừng</button></div><p>{{selected.error || 'Chỉ so sánh điểm loss/metric trên train; seed nào tốt hơn ở OOS chưa được xác minh.'}}</p><div class="table-wrap"><table><thead><tr><th>Seed</th><th>Trạng thái</th><th>Epoch đã chạy</th><th>Epoch hợp lệ</th><th>Loss train tốt nhất</th><th>Lý do</th></tr></thead><tbody><tr v-for="result in selected.results" :key="result.seed"><td>{{result.seed}}</td><td>{{result.status}}</td><td>{{result.completed_epochs ?? '—'}}</td><td>{{result.eligible_epochs ?? '—'}}</td><td>{{result.best_epoch?.loss ?? '—'}}</td><td>{{result.error || '—'}}</td></tr></tbody></table></div></div>
    <details v-if="scope" class="box"><summary>Phạm vi tham số native</summary><p>{{scope.per_parameter_override.reason}} {{scope.per_parameter_override.safe_action}}</p><div class="table-wrap"><table><thead><tr><th>Tham số</th><th>Nhóm</th><th>Low</th><th>High</th><th>Mặc định</th></tr></thead><tbody><tr v-for="field in scope.parameters" :key="field.name"><td>{{field.name}}</td><td>{{field.space}}</td><td>{{field.low}}</td><td>{{field.high}}</td><td>{{field.value}}</td></tr></tbody></table></div></details>
  </div>
</template>

<style scoped>
.seed{line-height:1.5;margin-top:26px;border-top:1px solid var(--line);padding-top:20px}.seed p{color:var(--fg-2)}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.grid label{font-size:12px}.grid input,.grid select{display:block;width:100%;margin-top:5px;padding:8px;background:var(--bg);color:var(--fg);border:1px solid var(--line-2);border-radius:6px}.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin:14px 0}.actions h4{margin-right:auto}button{padding:8px 12px;background:var(--bg-2);color:var(--fg);border:1px solid var(--line-2);border-radius:7px;cursor:pointer}button:disabled{opacity:.5}.box{padding:15px;margin:15px 0;border:1px solid var(--line);border-radius:9px}.error{color:#ffb4b4}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:8px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}summary{cursor:pointer}@media(max-width:800px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:550px){.grid{grid-template-columns:1fr}}
</style>
